var t=`1303-quindim`;var n=`world-1303`;var r=`BR`;var a=`south-america`;var o=8;var u=163;var s={en:`Quindim`,ua:`Квіндін`};var g={en:`Quindim is a dish from Brazil featuring chicken egg, desiccated coconut, coconut milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Квіндін, страва кухні країни Бразилія з такими основними складниками: куряче яйце, кокосова стружка, кокосове молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Separate seven egg yolks and whisk them with sugar without over-aerating; keep unused whites refrigerated for another recipe.`,ua:`Відділіть сім жовтків і змішайте їх із цукром без надмірного збивання; невикористані білки зберігайте охолодженими для інших страв.`,t:[`mixing`],m:10,i:[[`chicken-egg`,7,`pcs`],[`white-granulated-sugar`,220,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`desiccated-coconut`,210,`g`],[`unsalted-butter`,40,`g`],[`coconut-milk`,160,`ml`]]},{en:`Butter the small molds and sprinkle the sugar evenly on their interiors so the quindim releases after baking.`,ua:`Змастіть маленькі форми маслом і рівномірно присипте внутрішні стінки цукром, щоб квіндін легко вийшов після випікання.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[[`white-granulated-sugar`,70,`g`],[`unsalted-butter`,40,`g`]]},{en:`Bake the coconut-yolk custards in a hot-water bath at 160°C until fully set; cool thoroughly before unmolding.`,ua:`Випікайте кокосово-жовткові пудинги на водяній бані при 160°C до повного застигання; ретельно остудіть перед вийманням із форм.`,t:[`baking`],m:45,i:[]},{en:`Refrigerate the prepared mixture for about 90 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 90 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:90,i:[]}];var l={slug:t,id:n,country:`BR`,region:a,servings:8,minutes:163,title:s,text:g,steps:d};export{r as country,l as default,n as id,u as minutes,a as region,o as servings,t as slug,d as steps,g as text,s as title};